total = 0
broken = 0
try:
    with open("data.txt", encoding="utf-8") as f:
        for line in f:
            parts = line.split(";")
            try:
                total += int(parts[1])
            except (ValueError, IndexError):
                broken += 1
except FileNotFoundError:
    print("файла нет")
else:
    print(f"сумма: {total}")
    print(f"пропущено: {broken}")

